const json = pm.response.json();
// 自诊断：上传失败 90% 不是接口的问题，而是 Postman 没能读到本地文件
// 典型特征：msg 为 null（空字段）或含 is null / ContentType（Spring 收到 null MultipartFile）
if (json.code !== 200) {
  const m = String(json.msg || "");
  console.warn("上传失败，原始响应：" + JSON.stringify(json));
  if (json.msg === null || m.indexOf("is null") >= 0 || m.indexOf("ContentType") >= 0) {
    console.warn("👉 服务端没收到任何文件。请到 Body → form-data → file 行点 Select Files 手动选一次文件。");
  }
}
pm.test("业务 code = 200（上传成功）", () => pm.expect(json.code, JSON.stringify(json)).to.eql(200));
pm.test("返回 url / fileName / newFileName / originalFilename", () => {
  pm.expect(json).to.have.property("url");
  pm.expect(json).to.have.property("fileName");
  pm.expect(json).to.have.property("newFileName");
  pm.expect(json).to.have.property("originalFilename");
});
pm.environment.set("fileName", json.fileName);
pm.environment.set("uploadedUrl", json.url);
console.log("上传成功，访问地址：" + json.url);
